L000017	\title{Spin interferometry in a beam of ultracold molecules}
L000018	\author{R. A. Jenkins\orcidlink{0000-0002-6181-9824}}\thanks{These authors contributed equally to this work.}
L000019	\author{M. T. Ziemba\orcidlink{0009-0006-0691-1464}}\thanks{These authors contributed equally to this work.}
